import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [o for _, o in history]
    me = [s for s, _ in history]

    opp_def = opp.count('D')
    my_def = me.count('D')
    opp_c = n - opp_def

    # Endgame: defect in the final rounds once mutual cooperation is less valuable.
    if n >= 98:
        return 'D'

    # Opponent's recent defection streak.
    recent_def = 0
    for x in reversed(opp):
        if x == 'D':
            recent_def += 1
        else:
            break

    # Track recent window.
    window = opp[-12:] if n >= 12 else opp
    window_def = window.count('D')

    # Confirmed highly-defective partner: minimize losses.
    if n >= 6 and opp_def * 2 >= n + 2 and opp_def >= 4:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Strong recent defection: retaliate.
    if recent_def >= 3:
        return 'D'

    if recent_def == 2:
        # Punish, but leave a door open for repair.
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if recent_def == 1:
        # Tit-for-tat style single retaliation, but forgive quickly.
        if me and me[-1] == 'D' and n >= 2 and opp[-2] == 'C':
            # We already retaliated; return to cooperation.
            return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent has been cooperating (no recent defection).
    if n >= 8 and window_def == 0:
        # Established mutual cooperation: preserve it, with rare endgame exploit.
        if n >= 90:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    if n >= 8 and window_def <= 1:
        # Mostly cooperative partner: keep cooperating.
        return 'C'

    # Moderate defection rate: mostly defect to limit exploitation,
    # occasionally cooperate to allow recovery.
    if n >= 6:
        rate = opp_def / float(n)
        if rate > 0.6:
            if rng.random() < 0.07:
                return 'C'
            return 'D'
        if rate > 0.35:
            if rng.random() < 0.35:
                return 'C'
            return 'D'

    # Early game / unclear: cooperate to allow mutual benefit.
    if n < 6:
        return 'C'

    # Default conciliatory restoration.
    return 'C'
